# find marker cells (8), bg 4. diff at (2,9),(4,2),(7,2),(11,5) -> 4->2. Those are gaps in the rectangle outline?
# rect: rows 0..11, cols 2..9. Outline of 8: top row0 all 8; col2 rows0-11 should be 8 but (4,2) is 4 -> filled with 2.
# Check whether all diff cells lie on a missing side cell of the full 8-rectangle.
def solve(g):
    from collections import Counter
    h=len(g); w=len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=[r[:] for r in g]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if g[i][j]==bg and (i in(r0,r1) or j in(c0,c1)):
                out[i][j]=2
    return out
for k in ['Demo pair 1','Demo pair 2']:
    print(k, solve(G[k+' input'])==G[k+' output'])
